"""Domain objects and exact money helpers (money is kept as integer pennies)."""
from __future__ import annotations

import datetime
from dataclasses import dataclass, field
from decimal import Decimal
from typing import List, Tuple


@dataclass
class Product:
    sku: str
    name: str
    price: Decimal
    reorder: int
    tax: str = "standard"
    line: int = 0


@dataclass
class Movement:
    date: datetime.date
    sku: str
    quantity: int
    note: str = ""
    line: int = 0


@dataclass
class Order:
    id: str
    date: datetime.date
    customer: str
    lines: List[Tuple[str, int]] = field(default_factory=list)
    line: int = 0


@dataclass
class QuoteLine:
    sku: str
    quantity: int
    unit: Decimal
    gross: Decimal
    discount: Decimal
    net: Decimal


@dataclass
class Quote:
    lines: List[QuoteLine]
    subtotal: Decimal
    order_discount: Decimal
    tax: Decimal
    total: Decimal


def half_up_div(n: int, d: int) -> int:
    """n / d rounded half up, for n >= 0 and d > 0."""
    return (2 * n + d) // (2 * d)


def money(pennies: int) -> Decimal:
    """Exact two-decimal Decimal for an integer number of pennies."""
    digits = str(abs(pennies)).rjust(3, "0")
    sign = "-" if pennies < 0 else ""
    return Decimal("%s%s.%s" % (sign, digits[:-2], digits[-2:]))


def pennies(amount: Decimal) -> int:
    """Integer pennies of a Decimal amount (half up past two places)."""
    sign, digits, exp = amount.as_tuple()
    n = int("".join(map(str, digits)) or "0")
    shift = exp + 2
    if shift >= 0:
        n *= 10 ** shift
    else:
        n = half_up_div(n, 10 ** (-shift))
    return -n if sign else n
"""Reading the three text files: strict, line-numbered parsing."""
from __future__ import annotations

import datetime
import re
import sys
from typing import Dict, Iterator, List, Tuple

from .models import Movement, Order, Product, money

# Quantities and prices may have thousands of digits; do not let the
# interpreter's int<->str conversion limit (3.11+) turn them into errors.
if hasattr(sys, "set_int_max_str_digits"):
    sys.set_int_max_str_digits(0)

_WS = " \t"
_SKU = re.compile(r"[A-Za-z]{2,4}-[0-9]{3}")
_ORDER_ID = re.compile(r"[Ss][Oo]-[0-9]+")
_DATE = re.compile(r"([0-9]{4})-([0-9]{2})-([0-9]{2})")
_PRICE = re.compile(r"([0-9]+)(?:\.([0-9]{1,2}))?")
_DIGITS = re.compile(r"[0-9]+")
_SIGNED = re.compile(r"[+-]?[0-9]+")
_MOVE = re.compile(r"([^ \t]+)[ \t]+([^ \t]+)[ \t]+([^ \t]+)(?:[ \t]+(.*))?", re.S)
_FIELD_SEP = re.compile(r"[ \t]+")
TAX_RATES = {"standard": 20, "reduced": 5, "zero": 0}


class ParseError(ValueError):
    """A mistake in one of the data files; `.line` is the 1-based line."""

    def __init__(self, line: int, message: str):
        self.line = line
        self.message = message
        super().__init__("line %d: %s" % (line, message))

    def __reduce__(self):
        return (self.__class__, (self.line, self.message))


def records(text: str) -> Iterator[Tuple[int, str]]:
    """Yield (line number, trimmed line) for every non-blank, non-comment line."""
    if text.startswith("﻿"):
        text = text[1:]
    for number, raw in enumerate(text.split("\n"), 1):
        if raw.endswith("\r"):
            raw = raw[:-1]
        line = raw.strip(_WS)
        if line and not line.startswith("#"):
            yield number, line


def next_line_number(text: str) -> int:
    """Physical line number a line appended to `text` would get."""
    parts = text.split("\n")
    return len(parts) if parts[-1] == "" else len(parts) + 1


def parse_date(token: str):
    """A real YYYY-MM-DD calendar date, or None."""
    m = _DATE.fullmatch(token)
    if not m:
        return None
    try:
        return datetime.date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
    except ValueError:
        return None


def normalise_sku(token: str):
    """Upper-case SKU if `token` is well formed, else None."""
    return token.upper() if _SKU.fullmatch(token) else None


def normalise_order_id(token: str):
    return token.upper() if _ORDER_ID.fullmatch(token) else None


def parse_catalog(text: str) -> Dict[str, Product]:
    catalog: Dict[str, Product] = {}
    for n, line in records(text):
        fields = [f.strip(_WS) for f in line.split("|")]
        if len(fields) not in (4, 5):
            raise ParseError(n, "expected 4 or 5 fields separated by '|', found %d" % len(fields))
        raw_sku, name, raw_price, raw_reorder = fields[:4]
        sku = normalise_sku(raw_sku)
        if sku is None:
            raise ParseError(n, "bad SKU %r (want like AB-100)" % raw_sku)
        if sku in catalog:
            raise ParseError(n, "duplicate SKU %s (first on line %d)" % (sku, catalog[sku].line))
        if not name:
            raise ParseError(n, "empty product name")
        m = _PRICE.fullmatch(raw_price)
        if not m:
            raise ParseError(n, "bad price %r (want pounds with at most 2 decimals)" % raw_price)
        pence = int(m.group(1)) * 100 + int((m.group(2) or "").ljust(2, "0"))
        if pence < 1:
            raise ParseError(n, "price %r is below 0.01" % raw_price)
        if not _DIGITS.fullmatch(raw_reorder):
            raise ParseError(n, "bad reorder level %r (want a whole number, 0 or more)" % raw_reorder)
        tax = "standard"
        if len(fields) == 5:
            tax = fields[4].lower() if fields[4].isascii() else fields[4]
            if tax not in TAX_RATES:
                raise ParseError(n, "bad tax %r (want standard, reduced or zero)" % fields[4])
        catalog[sku] = Product(sku, name, money(pence), int(raw_reorder), tax, n)
    return catalog


def check_stock(movements: List[Movement]) -> None:
    """Raise ParseError on the first movement (in counting order) that takes stock below zero."""
    balance: Dict[str, int] = {}
    for m in sorted(movements, key=lambda mv: mv.date):
        balance[m.sku] = balance.get(m.sku, 0) + m.quantity
        if balance[m.sku] < 0:
            raise ParseError(m.line, "stock of %s would go below zero on %s" % (m.sku, m.date.isoformat()))


def parse_movements(text: str, catalog: Dict[str, Product]) -> List[Movement]:
    movements: List[Movement] = []
    for n, line in records(text):
        m = _MOVE.fullmatch(line)
        if not m:
            raise ParseError(n, "expected DATE SKU QUANTITY [NOTE]")
        raw_date, raw_sku, raw_qty, note = m.group(1), m.group(2), m.group(3), m.group(4)
        date = parse_date(raw_date)
        if date is None:
            raise ParseError(n, "bad date %r (want a real YYYY-MM-DD date)" % raw_date)
        sku = normalise_sku(raw_sku)
        if sku is None or sku not in catalog:
            raise ParseError(n, "unknown SKU %r (not in catalogue)" % raw_sku)
        if not _SIGNED.fullmatch(raw_qty) or int(raw_qty) == 0:
            raise ParseError(n, "bad quantity %r (want a non-zero whole number)" % raw_qty)
        movements.append(Movement(date, sku, int(raw_qty), (note or "").strip(_WS), n))
    check_stock(movements)
    return movements


def parse_orders(text: str, catalog: Dict[str, Product]) -> List[Order]:
    orders: List[Order] = []
    seen: Dict[str, int] = {}
    for n, line in records(text):
        fields = _FIELD_SEP.split(line)
        if len(fields) != 4:
            raise ParseError(n, "expected ORDER DATE CUSTOMER LINES, found %d fields" % len(fields))
        raw_id, raw_date, customer, raw_lines = fields
        order_id = normalise_order_id(raw_id)
        if order_id is None:
            raise ParseError(n, "bad order id %r (want like SO-1001)" % raw_id)
        if order_id in seen:
            raise ParseError(n, "duplicate order %s (first on line %d)" % (order_id, seen[order_id]))
        date = parse_date(raw_date)
        if date is None:
            raise ParseError(n, "bad date %r (want a real YYYY-MM-DD date)" % raw_date)
        lines: List[Tuple[str, int]] = []
        used = set()
        for piece in raw_lines.split(","):
            sku_part, star, qty_part = piece.partition("*")
            sku = normalise_sku(sku_part) if star else None
            if sku is None:
                raise ParseError(n, "bad order line %r (want SKU*QUANTITY)" % piece)
            if sku not in catalog:
                raise ParseError(n, "unknown SKU %r (not in catalogue)" % sku_part)
            if sku in used:
                raise ParseError(n, "SKU %s repeated in the order" % sku)
            if not _DIGITS.fullmatch(qty_part) or int(qty_part) < 1:
                raise ParseError(n, "bad quantity %r (want a whole number, 1 or more)" % qty_part)
            used.add(sku)
            lines.append((sku, int(qty_part)))
        seen[order_id] = n
        orders.append(Order(order_id, date, customer, lines, n))
    return orders
"""Stock levels, low-stock list and per-product history."""
from __future__ import annotations

from typing import Dict, List, Tuple

from .models import Movement, Product


def sorted_movements(movements: List[Movement]) -> List[Movement]:
    """Movements in the order they count: by date, same-day in file order."""
    return sorted(movements, key=lambda m: m.date)


def stock_levels(catalog: Dict[str, Product], movements: List[Movement]) -> Dict[str, int]:
    levels = {sku: 0 for sku in catalog}
    for m in movements:
        if m.sku in levels:
            levels[m.sku] += m.quantity
    return levels


def stock_status(onhand: int, reorder: int) -> str:
    if onhand == 0:
        return "out"
    return "low" if onhand <= reorder else "ok"


def buy_quantity(onhand: int, reorder: int) -> int:
    return max(1, 2 * reorder - onhand)


def history(sku: str, movements: List[Movement]) -> List[Tuple[Movement, int]]:
    """Movements of `sku` in counting order, each with the balance after it."""
    rows = []
    balance = 0
    for m in sorted_movements(movements):
        if m.sku == sku:
            balance += m.quantity
            rows.append((m, balance))
    return rows
"""Exact penny pricing, shipping, invoicing and the order report."""
from __future__ import annotations

import datetime
from dataclasses import dataclass
from decimal import Decimal
from typing import Dict, List, Optional, Tuple

from .models import Movement, Order, Product, Quote, QuoteLine, half_up_div, money, pennies
from .parsing import TAX_RATES
from .shelves import sorted_movements


def price_order(order: Order, catalog: Dict[str, Product]) -> Quote:
    rows = []  # (product, qty, unit, gross, discount, net) in pennies
    for sku, qty in order.lines:
        product = catalog[sku]
        unit = pennies(product.price)
        gross = qty * unit
        pct = 10 if qty >= 50 else 5 if qty >= 10 else 0
        discount = half_up_div(gross * pct, 100)
        rows.append((product, qty, unit, gross, discount, gross - discount))
    subtotal = sum(r[5] for r in rows)
    order_discount = half_up_div(subtotal * 3, 100) if subtotal >= 50000 else 0

    shares = [0] * len(rows)
    if order_discount:
        parts = [divmod(order_discount * r[5], subtotal) for r in rows]
        shares = [p[0] for p in parts]
        leftover = order_discount - sum(shares)
        by_remainder = sorted(range(len(rows)), key=lambda i: (-parts[i][1], i))
        for i in by_remainder[:leftover]:
            shares[i] += 1

    tax = 0
    for r, share in zip(rows, shares):
        tax += half_up_div((r[5] - share) * TAX_RATES[r[0].tax], 100)
    lines = [
        QuoteLine(r[0].sku, r[1], money(r[2]), money(r[3]), money(-r[4]), money(r[5]))
        for r in rows
    ]
    return Quote(lines, money(subtotal), money(-order_discount), money(tax),
                 money(subtotal - order_discount + tax))


def shipped_quantities(order: Order, movements: List[Movement]) -> List[int]:
    """Units shipped so far for each order line (capped at the ordered quantity)."""
    note = "order " + order.id
    out = []
    for sku, qty in order.lines:
        sent = sum(-m.quantity for m in movements
                   if m.sku == sku and m.quantity < 0 and m.note == note)
        out.append(min(sent, qty))
    return out


def order_status(order: Order, shipped: List[int]) -> str:
    if all(s >= q for (_, q), s in zip(order.lines, shipped)):
        return "complete"
    return "open" if not any(shipped) else "partial"


def invoice_order(order: Order, movements: List[Movement], catalog: Dict[str, Product]) -> Optional[Quote]:
    """Quote for what has shipped, or None when nothing has."""
    shipped = shipped_quantities(order, movements)
    lines = [(sku, s) for (sku, _), s in zip(order.lines, shipped) if s > 0]
    if not lines:
        return None
    return price_order(Order(order.id, order.date, order.customer, lines, order.line), catalog)


@dataclass
class FulfilLine:
    sku: str
    shipped: int
    backordered: int


@dataclass
class FulfilResult:
    lines: List[FulfilLine]
    movements: List[Movement]
    status: str


def fulfil(order: Order, on: datetime.date, movements: List[Movement], first_line: int = 0) -> FulfilResult:
    """Work out what ships on `on` and the movements that record it."""
    ordered = sorted_movements(movements)
    already = shipped_quantities(order, movements)
    new: List[Movement] = []
    for (sku, qty), sent in zip(order.lines, already):
        at_date = 0
        later_min = None
        balance = 0
        for m in ordered:
            if m.sku != sku:
                continue
            balance += m.quantity
            if m.date <= on:
                at_date = balance
            else:
                later_min = balance if later_min is None else min(later_min, balance)
        available = at_date if later_min is None else min(at_date, later_min)
        ship = min(qty - sent, max(0, available))
        if ship > 0:
            line = first_line + len(new) if first_line else 0
            new.append(Movement(on, sku, -ship, "order " + order.id, line))
    after = shipped_quantities(order, list(movements) + new)
    lines = [FulfilLine(sku, after[i] - already[i], qty - after[i])
             for i, (sku, qty) in enumerate(order.lines)]
    return FulfilResult(lines, new, order_status(order, after))


@dataclass
class ReportRow:
    order: str
    date: datetime.date
    customer: str
    status: str
    ordered: int
    shipped: int
    quoted: Decimal
    invoiced: Decimal


def report_rows(catalog: Dict[str, Product], movements: List[Movement], orders: List[Order]) -> List[ReportRow]:
    def sort_key(o: Order) -> Tuple:
        digits = o.id[3:].lstrip("0")
        return (o.date, len(digits), digits, o.id)

    rows = []
    for o in sorted(orders, key=sort_key):
        shipped = shipped_quantities(o, movements)
        invoice = invoice_order(o, movements, catalog)
        rows.append(ReportRow(
            o.id, o.date, o.customer, order_status(o, shipped),
            sum(q for _, q in o.lines), sum(shipped),
            price_order(o, catalog).total,
            invoice.total if invoice else money(0),
        ))
    return rows

"""The `stockroom` command: a small hand-written argument parser and the commands."""
from __future__ import annotations

import csv
import io
import json
import os
import re
import sys
from typing import Dict, List, Optional, Tuple

from .models import Movement
from .orders import fulfil, invoice_order, price_order, report_rows
from .parsing import (ParseError, check_stock, next_line_number, normalise_order_id,
                      normalise_sku, parse_catalog, parse_date, parse_movements, parse_orders)
from .shelves import buy_quantity, history, stock_levels, stock_status

USAGE = (
    "usage: stockroom [--dir DIR] stock|low [--json] | history SKU [--json] | "
    "receive|ship DATE SKU QTY [NOTE] | quote|invoice ORDER [--json] | "
    "fulfil ORDER DATE | report [--format text|csv|json]"
)

_JSON_COMMANDS = {"stock", "low", "history", "quote", "invoice"}
_ARITY = {"stock": (0, 0), "low": (0, 0), "history": (1, 1), "receive": (3, 4), "ship": (3, 4),
          "quote": (1, 1), "fulfil": (2, 2), "invoice": (1, 1), "report": (0, 0)}
_NEEDS = {"stock": "cm", "low": "cm", "history": "cm", "receive": "cm", "ship": "cm",
          "quote": "co", "fulfil": "cmo", "invoice": "cmo", "report": "cmo"}
_FILES = {"c": "catalog.txt", "m": "movements.txt", "o": "orders.txt"}
_QTY = re.compile(r"[0-9]+")


class Exit(Exception):
    def __init__(self, code: int, message: str):
        super().__init__(message)
        self.code = code
        self.message = message


def usage(message: str) -> Exit:
    return Exit(2, "%s\n%s" % (message, USAGE))


def refuse(message: str) -> Exit:
    return Exit(1, message)


# ----------------------------------------------------------------- arguments

def parse_args(argv: List[str]):
    """Return (command, positionals, options, dir). Raises Exit(2) on any command-line fault."""
    directory = "."
    rest: List[str] = []
    i = 0
    while i < len(argv):
        arg = argv[i]
        if arg == "--dir":
            if i + 1 >= len(argv):
                raise usage("option --dir needs a value")
            directory, i = argv[i + 1], i + 2
        elif arg.startswith("--dir="):
            directory, i = arg[len("--dir="):], i + 1
        else:
            rest.append(arg)
            i += 1
    if directory == "":
        raise usage("--dir needs a non-empty value")
    if not rest:
        raise usage("no command given")
    command, args = rest[0], rest[1:]
    if command not in _ARITY:
        raise usage("unknown command %r" % command)

    options: Dict[str, object] = {}
    if command in ("receive", "ship", "fulfil"):
        positional = args
    else:
        positional = []
        j = 0
        while j < len(args):
            arg = args[j]
            if arg == "--json" and command in _JSON_COMMANDS:
                options["json"] = True
            elif command == "report" and (arg == "--format" or arg.startswith("--format=")):
                if arg == "--format":
                    if j + 1 >= len(args):
                        raise usage("option --format needs a value")
                    j += 1
                    value = args[j]
                else:
                    value = arg[len("--format="):]
                if value not in ("text", "csv", "json"):
                    raise usage("bad --format value %r (want text, csv or json)" % value)
                options["format"] = value
            elif arg.startswith("-"):
                raise usage("unknown option %r" % arg)
            else:
                positional.append(arg)
            j += 1
    low, high = _ARITY[command]
    if not low <= len(positional) <= high:
        raise usage("wrong number of arguments for %s" % command)
    if command in ("receive", "ship") and parse_date(positional[0]) is None:
        raise usage("bad DATE %r (want a real YYYY-MM-DD date)" % positional[0])
    if command == "fulfil" and parse_date(positional[1]) is None:
        raise usage("bad DATE %r (want a real YYYY-MM-DD date)" % positional[1])
    return command, positional, options, directory


# --------------------------------------------------------------------- files

def _path(directory: str, name: str) -> str:
    return name if directory == "." else os.path.join(directory, name)


def read_files(directory: str, needs: str) -> Dict[str, Tuple[bytes, str]]:
    """Read and decode the needed files; a missing catalogue is fatal, the others are empty."""
    out: Dict[str, Tuple[bytes, str]] = {}
    for key in "cmo":
        if key not in needs:
            continue
        path = _path(directory, _FILES[key])
        try:
            with open(path, "rb") as handle:
                raw = handle.read()
        except FileNotFoundError:
            if key == "c" or not os.path.isdir(directory):
                raise Exit(2, "%s: cannot read file: not found" % path)
            raw = b""
        except OSError as err:
            raise Exit(2, "%s: cannot read file: %s" % (path, err.strerror or err))
        try:
            out[key] = (raw, raw.decode("utf-8"))
        except UnicodeDecodeError:
            raise Exit(2, "%s: cannot read file: not valid UTF-8" % path)
    return out


def parse_files(directory: str, files: Dict[str, Tuple[bytes, str]]):
    """Parse in catalogue, movements, orders order; the first mistake wins (exit 1)."""
    catalog = movements = orders = None
    name = _FILES["c"]
    try:
        catalog = parse_catalog(files["c"][1])
        if "m" in files:
            name = _FILES["m"]
            movements = parse_movements(files["m"][1], catalog)
        if "o" in files:
            name = _FILES["o"]
            orders = parse_orders(files["o"][1], catalog)
    except ParseError as err:
        raise refuse("%s: %s" % (_path(directory, name), err))
    return catalog, movements, orders


def append_movements(directory: str, raw: bytes, new: List[Movement]) -> None:
    data = b""
    if raw and not raw.endswith(b"\n"):
        data = b"\n"
    data += "".join(format_movement(m) + "\n" for m in new).encode("utf-8")
    path = _path(directory, _FILES["m"])
    try:
        with open(path, "ab") as handle:
            handle.write(data)
    except OSError as err:
        raise Exit(2, "%s: cannot write file: %s" % (path, err.strerror or err))


def format_movement(m: Movement) -> str:
    text = "%s %s %+d" % (m.date.isoformat(), m.sku, m.quantity)
    return text + " " + m.note if m.note else text


# ------------------------------------------------------------------ commands

def dump_json(value) -> str:
    return json.dumps(value, indent=2, ensure_ascii=False) + "\n"


def quote_output(header: str, order, quote, as_json: bool) -> str:
    if as_json:
        return dump_json({
            "order": order.id, "date": order.date.isoformat(), "customer": order.customer,
            "lines": [{"sku": l.sku, "quantity": l.quantity, "unit": str(l.unit),
                       "gross": str(l.gross), "discount": str(l.discount), "net": str(l.net)}
                      for l in quote.lines],
            "subtotal": str(quote.subtotal), "order_discount": str(quote.order_discount),
            "tax": str(quote.tax), "total": str(quote.total)})
    out = [header]
    out += ["%s %d %s %s %s %s" % (l.sku, l.quantity, l.unit, l.gross, l.discount, l.net)
            for l in quote.lines]
    out += ["subtotal %s" % quote.subtotal, "order discount %s" % quote.order_discount,
            "tax %s" % quote.tax, "total %s" % quote.total]
    return "\n".join(out) + "\n"


def lines_out(lines: List[str]) -> str:
    return "".join(l + "\n" for l in lines)


def find_order(orders, token: str):
    order_id = normalise_order_id(token)
    for order in orders:
        if order.id == order_id:
            return order
    raise refuse("order %s is not in orders.txt" % token)


def run(argv: List[str]) -> str:
    command, pos, options, directory = parse_args(argv)
    files = read_files(directory, _NEEDS[command])
    catalog, movements, orders = parse_files(directory, files)
    as_json = bool(options.get("json"))

    if command in ("stock", "low"):
        levels = stock_levels(catalog, movements)
        rows = []
        for sku in sorted(catalog):
            p, onhand = catalog[sku], levels[sku]
            status = stock_status(onhand, p.reorder)
            if command == "stock":
                rows.append({"sku": sku, "name": p.name, "onhand": onhand, "status": status})
            elif status != "ok":
                rows.append({"sku": sku, "onhand": onhand, "reorder": p.reorder,
                             "buy": buy_quantity(onhand, p.reorder)})
        if as_json:
            return dump_json(rows)
        keys = ("sku", "onhand", "status", "name") if command == "stock" else \
            ("sku", "onhand", "reorder", "buy")
        return lines_out([" ".join(str(r[k]) for k in keys) for r in rows])

    if command == "history":
        sku = normalise_sku(pos[0])
        if sku not in catalog:
            raise refuse("unknown SKU %s" % pos[0])
        rows = history(sku, movements)
        if as_json:
            return dump_json([{"date": m.date.isoformat(), "delta": "%+d" % m.quantity,
                               "balance": bal, "note": m.note} for m, bal in rows])
        return lines_out(["%s %+d %d%s" % (m.date.isoformat(), m.quantity, bal,
                                           " " + m.note if m.note else "") for m, bal in rows])

    if command in ("receive", "ship"):
        return add_movement(command, pos, directory, files["m"], catalog, movements)

    if command == "quote":
        order = find_order(orders, pos[0])
        header = "%s %s %s" % (order.id, order.date.isoformat(), order.customer)
        return quote_output(header, order, price_order(order, catalog), as_json)

    if command == "invoice":
        order = find_order(orders, pos[0])
        quote = invoice_order(order, movements, catalog)
        if quote is None:
            raise refuse("nothing has shipped for order %s" % order.id)
        header = "invoice %s %s %s" % (order.id, order.date.isoformat(), order.customer)
        return quote_output(header, order, quote, as_json)

    if command == "fulfil":
        order = find_order(orders, pos[0])
        on = parse_date(pos[1])
        if on < order.date:
            raise refuse("date %s is before the order date %s" % (pos[1], order.date.isoformat()))
        result = fulfil(order, on, movements, next_line_number(files["m"][1]))
        if result.movements:
            append_movements(directory, files["m"][0], result.movements)
        return lines_out(["%s shipped %d backordered %d" % (l.sku, l.shipped, l.backordered)
                          for l in result.lines] + ["status " + result.status])

    return report(options.get("format", "text"), catalog, movements, orders)


def add_movement(command, pos, directory, file, catalog, movements) -> str:
    raw, text = file
    date = parse_date(pos[0])
    sku = normalise_sku(pos[1])
    if sku is None or sku not in catalog:
        raise refuse("unknown SKU %s" % pos[1])
    if not _QTY.fullmatch(pos[2]) or int(pos[2]) < 1:
        raise refuse("bad quantity %r (want a whole number, 1 or more)" % pos[2])
    note = pos[3].strip(" \t") if len(pos) > 3 else ""
    if "\n" in note or "\r" in note:
        raise refuse("note may not contain a line break")
    try:
        note.encode("utf-8")
    except UnicodeEncodeError:
        raise refuse("note is not valid text")
    quantity = int(pos[2]) * (1 if command == "receive" else -1)
    move = Movement(date, sku, quantity, note, next_line_number(text))
    try:
        check_stock(movements + [move])
    except ParseError as err:
        raise refuse("%s: %s" % (_path(directory, _FILES["m"]), err))
    append_movements(directory, raw, [move])
    return format_movement(move) + "\n"


def report(fmt: str, catalog, movements, orders) -> str:
    rows = report_rows(catalog, movements, orders)
    keys = ("order", "date", "customer", "status", "ordered", "shipped", "quoted", "invoiced")
    records = [{"order": r.order, "date": r.date.isoformat(), "customer": r.customer,
                "status": r.status, "ordered": r.ordered, "shipped": r.shipped,
                "quoted": str(r.quoted), "invoiced": str(r.invoiced)} for r in rows]
    if fmt == "json":
        return dump_json(records)
    if fmt == "csv":
        buf = io.StringIO()
        writer = csv.writer(buf, lineterminator="\n")
        writer.writerow(keys)
        for r in records:
            writer.writerow([r[k] for k in keys])
        return buf.getvalue()
    return lines_out(["%s %s %s %s %d/%d %s %s" % (
        r["order"], r["date"], r["customer"], r["status"], r["shipped"], r["ordered"],
        r["quoted"], r["invoiced"]) for r in records])


# ------------------------------------------------------------------- output

def _write(stream, text: str, errors: str) -> None:
    buffer = getattr(stream, "buffer", None)
    if buffer is not None:
        stream.flush()
        buffer.write(text.encode("utf-8", errors))
        buffer.flush()
    else:
        stream.write(text)
        stream.flush()


def _silence_stdout() -> None:
    """Point fd 1 at /dev/null so the interpreter's exit-time flush cannot fail again."""
    try:
        devnull = os.open(os.devnull, os.O_WRONLY)
        os.dup2(devnull, sys.stdout.fileno())
    except (OSError, ValueError, AttributeError):
        pass


def main(argv: Optional[List[str]] = None) -> int:
    args = list(sys.argv[1:] if argv is None else argv)
    try:
        output = run(args)
    except Exit as err:
        try:
            _write(sys.stderr, "stockroom: %s\n" % err.message, "backslashreplace")
        except (OSError, ValueError):
            pass
        return err.code
    try:
        if output:
            _write(sys.stdout, output, "surrogateescape")
    except (OSError, ValueError):
        _silence_stdout()
    return 0
